mapper.select:
SELECT 
FROM quality_nonconform n
LEFT JOIN base_equipment e ON e.equip_code = n.equip_code

    AND n.occur_date >= #{from}
    AND n.occur_date <= #{to}
    AND n.equip_code = #{equipCode}
    AND n.status = #{status}
    AND n.defect_code = #{defectCode}

        AND (n.nc_no LIKE CONCAT('%', #{keyword}, '%') OR n.part_no LIKE CONCAT('%', #{keyword}, '%')
             OR n.lot_no LIKE CONCAT('%', #{keyword}, '%') OR n.product_name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY n.occur_date DESC, n.nc_id DESC

mapper.update:
UPDATE quality_nonconform SET
    occur_date = #{occurDate}, equip_code = #{equipCode}, part_no = #{partNo}, product_name = #{productName},
    lot_no = #{lotNo}, defect_code = #{defectCode}, defect_name = #{defectName}, qty = #{qty}, unit = #{unit},
    status = #{status}, disposition = #{disposition}, action_note = #{actionNote}, remark = #{remark},
    upd_user_id = #{updUserId}, upd_user_name = #{updUserName}
WHERE nc_id = #{ncId}

mapper.select:
SELECT t.*, (SELECT COUNT(*) FROM quality_nonconform n WHERE n.defect_code = t.defect_code) AS use_count FROM quality_defect_type t
AND t.use_yn = #{useYn}
ORDER BY t.sort_order, t.defect_code
